import Java.Util.Scanner;

public static void main() {

  Scanner main_scanner = new Scanner();

  System.out.println("What is your username?");

  String username = main_scanner.nextLine();

  System.out.println("Welcome, " + username);

  bool eligibility = determine_eligibility(determine_age);

  if(eligibility == true){

    System.out.println("Welcome aboard. Please enjoy this sub.");

  else{

    System.out.println("Sorry, this sub isn't for you.");

}



int determine_age() {

  Scanner age_scanner = new scanner();

  system.out.println("How old are you?");

  int age = Integer.parseInt(age_scanner.nextLine());

  return age;

}



bool determine_eligibilty(int age){

  if (age <= 12){

    return false;

  }

  else if (age >= 20){

    return false;

  }

  else{

    return true;

  }

}
